import{z as B,x as A,o as n,c as p,q as s,j as i,D as t,d as E,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"NMI","description":"","frontmatter":{"title":"NMI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nmi.md","filePath":"cs/nmi.md","lastUpdated":1791063341000}'),d={name:"cs/nmi.md"};function I(M,a,N,m,C,D){const r=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=s('<h1 id="nmi" tabindex="-1">NMI <a class="header-anchor" href="#nmi" aria-label="Permalink to &quot;NMI&quot;">​</a></h1><div class="epigraph"><p>不可屏蔽中断在普通 IRQ 已关闭时仍能进入；它几乎不能拿常规锁，也不能走可推迟的下半部。</p><footer>—— 据 Bovet and Cesati, Understanding the Linux Kernel；Intel/AMD 与 RISC-V 特权手册对 NMI 的整理</footer></div><p><a href="/cs/irq-affinity">上一课</a>让可屏蔽设备 IRQ 可以绑核、可以推迟。<a href="/cs/exception-interrupt-entry">异常与中断入口</a>里的普通中断能被状态位关掉。缺口是：看门狗、机器检查、某些调试事件必须在「已经关中断」的路径上仍能打断 CPU——<strong>NMI</strong>。本课只钉它与普通 IRQ 的差别，不写处理器勘误表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核关本地中断是为了保护与 ISR 共享的数据。若死循环发生在关中断区间，普通时钟 IRQ 进不来，调度器救不了。NMI 绕过屏蔽，进入另一套入口：不重入或极窄重入、栈往往是专用 NMI 栈，避免在已损坏的内核栈上再压帧。缺口不是新的亲和掩码，而是承认存在<strong>不能推迟、不能睡、几乎不能拿自旋锁</strong>的上下文——因为锁的持有者可能正是被 NMI 打断的那条路径。</p><p><span class="marginnote">NMI 处理程序里打印、分配、拿 <code>spinlock</code> 都可能死锁。实践是：碰 per-CPU 无锁状态、触发崩溃转储、或只置位留给稍后的可屏蔽路径。</span></p><p><span class="marginnote">术语翻译：不可屏蔽就是用「绕过屏蔽位、硬件强制投递」的手段来做「CPU 再忙也必须听一下」的事——普通 IRQ 像可以拒接的电话，NMI 像火警铃，响不响不由你控制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件投递 NMI 向量。入口：切到 NMI 栈，保存最小状态，跑处理函数，退出时恢复屏蔽语义。看门狗：NMI 里检查「该核是否还在打卡」；若普通时钟长期未跑，判定锁死。本课不把 kdump 的全部协议写完。</p><p><span class="marginnote">直觉类比：看门狗像监考老师逐个看考生还在不在动笔——不替你做题，只负责发现有人「卡住不动」（关中断死循环）就记名叫停；NMI 保证老师随时能看，哪怕考生把门反锁（关中断）。</span></p>',10)),(n(),i(l,null,{default:t(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E6%99%AE%E9%80%9A%20IRQ%20%E5%8F%AF%E5%85%B3%22%5D%20--%3E%20STILL%5B%22NMI%20%E4%BB%8D%E5%8F%AF%E8%BF%9B%22%5D%0A%20%20STILL%20--%3E%20NMI%5B%22NMI%20%E6%A0%88%E4%B8%8E%E6%9E%81%E7%9F%AD%E5%A4%84%E7%90%86%22%5D%0A%20%20NMI%20--%3E%20LATER%5B%22%E8%87%B3%E5%A4%9A%E7%BD%AE%E4%BD%8D%2C%20%E7%95%99%E7%BB%99%E5%8F%AF%E5%B1%8F%E8%94%BD%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("与"),e("a",{href:"/cs/interrupt-bottom-half"},"中断下半部"),E("的纪律相反：NMI 没有标准下半部。想推迟，只能置标志，等下一次可屏蔽中断或调度点。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"NMI 把「关中断 = 原子」这句话限制成「对可屏蔽 IRQ 原子」。写内核的人必须假设 NMI 可以嵌在任何关中断区间。因此 per-CPU 统计若要在 NMI 里更新，要用 NMI 安全的原子或专用缓冲。这为后课内核抢占与 per-CPU 数据预告约束，本课不展开抢占计数。",-1)),a[6]||(a[6]=e("p",null,"不可用 NMI 来做普通设备完成通知：丢失与嵌套语义都太凶。",-1)),(n(),i(l,null,{default:t(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%91%A8%E6%9C%9F%E6%80%A7%20NMI%20%E6%97%B6%E9%92%9F%E6%89%93%E5%90%91%E6%AF%8F%E6%A0%B8%22%5D%20--%3E%20CK%5B%22NMI%20%E5%A4%84%E7%90%86%E5%87%BD%E6%95%B0%E8%AF%BB%E8%AF%A5%E6%A0%B8%E6%89%93%E5%8D%A1%E8%AE%A1%E6%95%B0%22%5D%0A%20%20CK%20--%3E%20CMP%7B%22%E8%AE%A1%E6%95%B0%E9%95%BF%E6%97%B6%E9%97%B4%E6%9C%AA%E5%8F%98%EF%BC%9F%22%7D%0A%20%20CMP%20--%3E%7C%22%E4%BB%8D%E5%9C%A8%E6%8E%A8%E8%BF%9B%22%7C%20OK%5B%22%E6%AD%A3%E5%B8%B8%EF%BC%8C%E7%AB%8B%E5%8D%B3%E8%BF%94%E5%9B%9E%22%5D%0A%20%20CMP%20--%3E%7C%22%E5%81%9C%E6%BB%9E%20%E2%87%92%20%E5%85%B3%E4%B8%AD%E6%96%AD%E5%8C%BA%E6%AD%BB%E5%BE%AA%E7%8E%AF%22%7C%20ALARM%5B%22%E8%AE%B0%E5%BD%95%E6%A0%88%EF%BC%9Apanic%20%E6%88%96%E8%BD%AC%E5%82%A8%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>这张图回答：看门狗怎么用 NMI 抓住锁死的核。NMI 独立于被检查内核的屏蔽状态，所以哪怕目标核把自己的普通中断全关了，探测与报警照样能发生——这正是普通时钟 IRQ 做不到的事。</p><p><span class="marginnote">常见误区：初学者容易想在 NMI 处理函数里直接打印或拿自旋锁。持有该锁的代码可能正被这次 NMI 打断——等它放锁等于等一条永远走不完的路径，同一路径重入同一把锁，死锁当场成立。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 SMM、机器检查异常的全部严重度分级写完，不讨论如何用 NMI 做隐蔽通道。也不把用户态「假 NMI」当对象：用户不能发真 NMI。</p><p>后课默认：存在不能屏蔽的入口。内核执行路径何时能被<strong>另一条内核线程</strong>抢走 CPU，下一课讲内核抢占。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NMI 绕过普通关中断；无标准下半部，几乎不能拿常规锁。</li><li>看门狗一类诊断依赖它；设备完成不要走它。</li><li>内核路径上的抢占是下一课。</li><li>出处：Bovet and Cesati；Love, <em>LKD</em>。</li></ul>',7))])}const f=B(d,[["render",I]]);export{c as __pageData,f as default};
